bool isself(dns_view_t *myview, dns_tsigkey_t *mykey,
   const isc_netaddr_t *srcaddr, const isc_netaddr_t *destaddr,
   dns_rdataclass_t rdclass, void *arg);
'isself' returns true if a non-recursive query from 'srcaddr' to 'destaddr' with optional key 'mykey' for class 'rdclass' would be delivered to 'myview'.

